const body = $input.first().json.body || $input.first().json;

const documentText = body.document_text || '';
const documentId   = body.document_id  || 'doc_' + Date.now();
const groundTruth  = body.ground_truth || null;

if (!documentText.trim()) {
  throw new Error('document_text is required and must not be empty');
}

// Normalise line endings
const normalizedText = documentText
  .split('\r\n').join('\n')
  .split('\r').join('\n')
  .trim();

// PII lives in the header — cap at 3 000 chars so Ollama stays fast
const piiSection = normalizedText.slice(0, 3000);

const stage1Body = JSON.stringify({
  document_id:   documentId,
  document_text: normalizedText,
  pii_section:   piiSection,
  ground_truth:  groundTruth
});

return [{
  json: {
    document_id:  documentId,
    text:         normalizedText,
    char_count:   normalizedText.length,
    ground_truth: groundTruth,
    stage1_body:  stage1Body
  }
}];

const input = $input.first().json;

const det  = input.pii_detection_eval || {};
const leak = input.context_leakage    || {};
const rev  = input.irreversibility    || {};

// ── Detection verdict ──────────────────────────────────────────────
const detVerdict = (det.precision != null)
  ? (det.recall >= 90 && det.precision >= 90
      ? 'GOOD'
      : det.recall >= 70
        ? 'ACCEPTABLE'
        : 'POOR')
  : 'NO_GROUND_TRUTH';

const report = {
  document_id:          input.document_id,
  status:               'stage1_complete',
  external_llm_called:  false,

  // ── Raw pipeline output ──────────────────────────────────────────
  pii_entities_detected: (input.pii_entities || []).length,
  pii_entities:          input.pii_entities  || [],
  mapping_size:          Object.keys(input.mapping || {}).length,
  pseudonymized_text:    input.pseudonymized_text || '',

  // ── A: PII Detection Quality ─────────────────────────────────────
  pii_detection: {
    verdict:            detVerdict,
    ground_truth_count: det.ground_truth_count  ?? null,
    detected_count:     det.detected_count       ?? 0,
    true_positives:     det.true_positives       ?? null,
    false_positives:    det.false_positives      ?? null,
    false_negatives:    det.false_negatives      ?? null,
    precision_pct:      det.precision            ?? null,
    recall_pct:         det.recall               ?? null,
    f1_score_pct:       det.f1_score             ?? null,
    fp_entities:        det.fp_entities          || [],
    fn_entities:        det.fn_entities          || [],
    note:               det.note                 || null
  },

  // ── B: Context Leakage ───────────────────────────────────────────
  context_leakage: {
    verdict:         leak.verdict         || 'UNKNOWN',
    leakage_free:    leak.leakage_free    ?? null,
    leaked_count:    leak.leaked_count    ?? 0,
    leaked_entities: leak.leaked_entities || [],
    note:            leak.note            || null
  },

  // ── C: Irreversibility ───────────────────────────────────────────
  irreversibility: {
    verdict:              rev.verdict              || 'UNKNOWN',
    high_risk_count:      rev.high_risk_count      ?? 0,
    medium_risk_count:    rev.medium_risk_count    ?? 0,
    low_risk_count:       rev.low_risk_count       ?? 0,
    high_risk_entities:   rev.high_risk_entities   || [],
    medium_risk_entities: rev.medium_risk_entities || [],
    risks:                rev.risks                || [],
    note:                 rev.note                 || null
  },

  // ── Privacy summary ───────────────────────────────────────────────
  privacy_summary: {
    pii_sent_to_external_llm:  false,
    real_pii_in_pseudonymized: !(leak.leakage_free),
    reversibility_verdict:     rev.verdict  || 'UNKNOWN',
    detection_verdict:         detVerdict
  }
};

return [{ json: report }];
